INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool---ninja-of-the-nth-dimension-europe', 'Genesis', 'Zool - Ninja of the ''Nth'' Dimension (Europe)', '1992', 'Platformer', 'Gremlin Graphics', '1', 'Action Platformer', 'Action-Platformer.', 'Dash through the 16-bit "Nth" dimension in Europe.', 'The official 16-bit European Zool release.', 'Zool features high-speed 16-bit platforming and ninja action. Master the 16-bit Sega zones with the iconic hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool---ninja-of-the-nth-dimension-usa', 'Genesis', 'Zool - Ninja of the ''Nth'' Dimension (USA)', '1992', 'Platformer', 'Gremlin Graphics', '1', 'Action Platformer', 'Action-Platformer.', 'Master the 16-bit ninja skills in the USA release.', 'The official 16-bit North American Zool game.', 'This 16-bit version brings the Amiga hit to the Genesis. Experience the fast-paced 16-bit Sega platforming at its best.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoom!-world', 'Genesis', 'Zoom! (World)', '1988', 'Puzzle', 'Electronic Arts', '1', 'Arcade Puzzle Action', 'Action-Puzzle.', 'Clear the 16-bit tiles in this pseudo-3D grid.', 'A unique and psychedelic 16-bit puzzle game.', 'Zoom! features fast-paced 16-bit tile-clearing logic. Experience the early 16-bit Sega puzzle power on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop-europe', 'Genesis', 'Zoop (Europe)', '1995', 'Puzzle', 'Mindscape', '2', 'Tile Matching Puzzle', 'Action-Puzzle.', 'Match the 16-bit shapes in the European edition.', 'The official 16-bit PAL Zoop release.', 'Zoop features 16-bit color-matching combat and high speed. Master the 16-bit Sega grid logic in this stylish puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop-usa', 'Genesis', 'Zoop (USA)', '1995', 'Puzzle', 'Mindscape', '2', 'Tile Matching Puzzle', 'Action-Puzzle.', 'Master the 16-bit Zoop grid in the USA release.', 'The official 16-bit North American Zoop game.', 'This 16-bit version offers addictive shape-matching gameplay. Prove your 16-bit Sega puzzle skills on your Genesis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zou!-zou!-zou!-rescue-daisakusen-japan', 'Genesis', 'Zou! Zou! Zou! Rescue Daisakusen (Japan)', '1995', 'Action', 'Sigma', '2', 'Arcade Action Platformer', 'Action-Platformer.', 'Join the 16-bit rescue mission in Japan.', 'A unique 16-bit platformer with rescue mechanics.', 'Zou! Zou! Zou! features charming 16-bit art and diverse heroes. Enjoy a fun and distinct 16-bit Sega challenge.');